import{jpegPDF,canvasBlob,saveBlob,shareFile,textLines}from './visual-export.mjs';
export function layoutTree(data){const nodes=(data.nodes||[]).map(n=>({...n,labels:[]})),byID=new Map(nodes.map(n=>[n.id,n])),edges=(data.edges||[]).filter(e=>byID.has(e.owner)&&byID.has(e.member)),adj=new Map(nodes.map(n=>[n.id,[]]));for(const e of edges){adj.get(e.owner).push([e.member,Number(e.generation)||0]);adj.get(e.member).push([e.owner,-Number(e.generation)||0]);byID.get(e.member).labels.push(e.label+' لـ '+byID.get(e.owner).name)}const seen=new Set,components=[],conflicts=[];for(const first of nodes){if(seen.has(first.id))continue;const ids=[],levels=new Map([[first.id,0]]),queue=[first.id];seen.add(first.id);for(let i=0;i<queue.length;i++){const id=queue[i];ids.push(id);for(const [next,delta]of adj.get(id)){const level=levels.get(id)+delta;if(!levels.has(next)){levels.set(next,level);seen.add(next);queue.push(next)}else if(levels.get(next)!==level)conflicts.push([id,next])}}components.push({ids,levels,linked:ids.length>1})}const linked=components.filter(c=>c.linked),isolates=components.filter(c=>!c.linked).flatMap(c=>c.ids);if(isolates.length)linked.push({ids:isolates,levels:new Map(isolates.map(id=>[id,0])),linked:false});let y=90,maxCols=1;const groups=[];for(const c of linked){const top=y;y+=55;const rows=[...new Set(c.levels.values())].sort((a,b)=>a-b);for(const level of rows){const row=c.ids.filter(id=>c.levels.get(id)===level);maxCols=Math.max(maxCols,Math.min(8,row.length));row.forEach((id,i)=>{const n=byID.get(id);n.x=30+(i%8)*230;n.y=y+Math.floor(i/8)*125;n.width=210;n.height=90;n.labels=[...new Set(n.labels)];n.unlinked=!c.linked});y+=Math.ceil(row.length/8)*125+55}groups.push({y:top,label:c.linked?'فرع مترابط':'أعضاء لم تُحدد صلات قرابتهم بعد'});y+=30}return{nodes,edges,groups,conflicts,width:Math.max(760,60+maxCols*230),height:Math.max(600,y+50)}}
export function drawTree(ctx,layout,title,{scale=1,top=0,page=1,pages=1,width=1600,height=1131}={}){ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);ctx.save();ctx.beginPath();ctx.rect(0,75,width,height-115);ctx.clip();ctx.translate(0,75-top*scale);ctx.scale(scale,scale);ctx.strokeStyle='#7b9eac';ctx.lineWidth=2;const map=new Map(layout.nodes.map(n=>[n.id,n]));for(const e of layout.edges){const a=map.get(e.owner),b=map.get(e.member);ctx.beginPath();ctx.moveTo(a.x+a.width/2,a.y+a.height/2);ctx.bezierCurveTo(a.x+a.width/2,(a.y+b.y)/2+45,b.x+b.width/2,(a.y+b.y)/2+45,b.x+b.width/2,b.y+b.height/2);ctx.stroke()}ctx.direction='rtl';ctx.textAlign='right';for(const g of layout.groups){if(g.y+50<top||g.y>top+(height-115)/scale)continue;ctx.fillStyle='#466a7b';ctx.font='bold 22px sans-serif';ctx.fillText(g.label,layout.width-30,g.y+28)}for(const n of layout.nodes){if(n.y+n.height<top||n.y>top+(height-115)/scale)continue;ctx.fillStyle=n.unlinked?'#f5f6f7':'#edf6f8';ctx.fillRect(n.x,n.y,n.width,n.height);ctx.strokeStyle='#cbdde3';ctx.strokeRect(n.x,n.y,n.width,n.height);ctx.textAlign='center';ctx.fillStyle='#143c4d';ctx.font='bold 20px sans-serif';const names=textLines(ctx,n.name,190).slice(0,2);names.forEach((s,i)=>ctx.fillText(s,n.x+105,n.y+28+i*24));ctx.fillStyle='#577080';ctx.font='14px sans-serif';const label=n.labels.join('، ')||'لم تُحدد صلة';ctx.fillText(label.length>40?label.slice(0,38)+'…':label,n.x+105,n.y+77)}ctx.restore();ctx.textAlign='right';ctx.direction='rtl';ctx.fillStyle='#123747';ctx.font='bold 26px sans-serif';ctx.fillText(title,width-35,43);ctx.font='18px sans-serif';ctx.fillStyle='#677b84';ctx.fillText('الصفحة '+page+' / '+pages+' · '+layout.nodes.length+' عضو · الصلات المؤكدة فقط',width-35,height-15)}
export async function wholeTree({rpc,state,element,button,busy,toast}){const d=element('dialog',undefined,'whole-tree-dialog'),head=element('header'),body=element('div');head.append(element('h2','شجرة العائلة الكاملة'),button('إغلاق',()=>{d.close();d.remove()}));d.append(head,body);document.body.append(d);d.showModal();let data,layout,zoom=1;const call=(action,payload={})=>rpc('whole_tree',{action,payload});async function load(){data=await call('get');if(!d.open)return;layout=layoutTree(data);render()}
 function render(){body.replaceChildren();body.append(element('p',data.name+' · '+layout.nodes.length+' عضو · '+layout.edges.length+' صلة مؤكدة'));if(layout.conflicts.length)body.append(element('p','توجد صلات قرابة متعارضة في ترتيب الأجيال. راجع الروابط المضافة.','danger'));body.append(element('p','كل وصف يوضح قرابة الاسم بصاحب العلاقة. الأعضاء بلا روابط مؤكدة يظهرون في قسم مستقل.','muted'));const tools=element('div',undefined,'tree-export-tools');tools.append(button('−',()=>resize(.8)),button('+',()=>resize(1.25)));if(data.admin)tools.append(button('حفظ PDF · A3',()=>busy(null,()=>exportPDF()),'primary'),button('صور للجوال',()=>busy(null,()=>exportMobile()),'secondary'));body.append(tools);const viewport=element('div',undefined,'whole-tree-viewport'),svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 '+layout.width+' '+layout.height);svg.setAttribute('width',layout.width);svg.setAttribute('height',layout.height);svg.setAttribute('role','img');svg.setAttribute('aria-label','الترابط بين جميع أعضاء العائلة');function shape(tag,attrs,text){const el=document.createElementNS(svg.namespaceURI,tag);for(const[k,v]of Object.entries(attrs))el.setAttribute(k,v);if(text!==undefined)el.textContent=text;svg.append(el);return el}const map=new Map(layout.nodes.map(n=>[n.id,n]));for(const e of layout.edges){const a=map.get(e.owner),b=map.get(e.member),x=a.x+105,y=a.y+45,xx=b.x+105,yy=b.y+45;shape('path',{d:`M ${x} ${y} C ${x} ${(y+yy)/2} ${xx} ${(y+yy)/2} ${xx} ${yy}`,fill:'none',stroke:'#8baab7','stroke-width':2})}for(const g of layout.groups)shape('text',{x:layout.width-30,y:g.y+28,'text-anchor':'end',fill:'#496b7b','font-size':22},g.label);for(const n of layout.nodes){const rect=shape('rect',{x:n.x,y:n.y,width:210,height:90,rx:12,fill:n.unlinked?'#f4f5f6':'#edf6f8',stroke:'#c9dce4'});const title=document.createElementNS(svg.namespaceURI,'title');title.textContent=n.name+' · '+n.labels.join('، ');rect.append(title);const name=shape('text',{x:n.x+105,y:n.y+30,'text-anchor':'middle','font-size':19,fill:'#153e4f'},n.name.length>25?n.name.slice(0,24)+'…':n.name);name.style.cursor='pointer';name.onclick=()=>document.dispatchEvent(new CustomEvent('family:member',{detail:{id:n.id}}));const labels=n.labels.join('، ')||'لم تُحدد صلة';shape('text',{x:n.x+105,y:n.y+67,'text-anchor':'middle','font-size':13,fill:'#597582'},labels.length>34?labels.slice(0,32)+'…':labels)}viewport.append(svg);body.append(viewport);function resize(f){zoom=Math.min(2.5,Math.max(.3,zoom*f));svg.setAttribute('width',layout.width*zoom);svg.setAttribute('height',layout.height*zoom)}if(data.admin){const enabled=element('input');enabled.type='checkbox';enabled.checked=!!data.public_enabled;enabled.disabled=!!state.readOnly;const label=element('label','إظهار شجرة العائلة لجميع الأعضاء في القائمة','inline');label.prepend(enabled);enabled.onchange=()=>busy(enabled,async()=>{await call('enable',{enabled:enabled.checked});document.dispatchEvent(new CustomEvent('family:tree-visibility'));toast('حُفظ خيار العرض.')});body.append(label);const form=element('form',undefined,'tree-link-editor');form.append(element('h3','تحديد صلة قرابة بين عضوين'));function select(label,rows){const l=element('label',label),s=element('select');s.required=true;s.append(element('option','اختر…'));s.firstChild.value='';for(const row of rows){const o=element('option',row.name||row.label);o.value=row.id||row.code;s.append(o)}l.append(s);form.append(l);return s}const owner=select('صاحب العلاقة',data.nodes),member=select('القريب',data.nodes),relation=select('القريب بالنسبة لصاحب العلاقة',data.options);form.append(element('p','مثال: صاحب العلاقة أحمد، والقريب علي، والصلة «أب» تعني أن عليًا أبو أحمد.','muted'));const save=element('button','اعتماد الصلة وإضافتها','primary');save.disabled=!!state.readOnly;form.append(save);form.onsubmit=e=>{e.preventDefault();return busy(save,async()=>{await call('link',{owner:owner.value,member:member.value,relation:relation.value});await load()})};body.append(form);const links=element('details');links.append(element('summary','إدارة الروابط المؤكدة'));for(const e of data.edges){const row=element('div',undefined,'tree-link-row');row.append(element('span',map.get(e.member).name+' · '+e.label+' لـ '+map.get(e.owner).name));const remove=button('إزالة',()=>busy(null,async()=>{await call('unlink',{owner:e.owner,member:e.member});await load()}),'text-button danger');remove.disabled=!!state.readOnly;row.append(remove);links.append(row)}body.append(links)}}
 function pages(width,height){const scale=width/layout.width,step=(height-115)/scale-30;return{scale,step,count:Math.max(1,Math.ceil(layout.height/step))}}
 async function exportPDF(){const width=1600,height=1131,p=pages(width,height),images=[];if(p.count>150)throw Error('الشجرة كبيرة جدًا. قلل الروابط المتعارضة أو صدّر صور الصفحات.');for(let i=0;i<p.count;i++){const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;drawTree(canvas.getContext('2d'),layout,'شجرة '+data.name,{width,height,scale:p.scale,top:i*p.step,page:i+1,pages:p.count});images.push({width,height,bytes:new Uint8Array(await(await canvasBlob(canvas)).arrayBuffer())});if(i%5===0)await new Promise(r=>setTimeout(r,0))}saveBlob(jpegPDF(images),'family-tree-A3.pdf')}
 async function exportMobile(){const preview=element('dialog',undefined,'tree-mobile-export');preview.append(element('h2','صور الشجرة للجوال'),button('إغلاق',()=>{preview.close();preview.remove()}));document.body.append(preview);preview.showModal();const width=1440,height=2560,p=pages(width,height);const pick=element('select');pick.setAttribute('aria-label','صفحة الشجرة');for(let i=0;i<p.count;i++){const o=element('option','الصفحة '+(i+1)+' من '+p.count);o.value=i;pick.append(o)}const image=element('img');image.alt='معاينة شجرة العائلة';let blob,url;async function paint(){const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;drawTree(canvas.getContext('2d'),layout,'شجرة '+data.name,{width,height,scale:p.scale,top:Number(pick.value)*p.step,page:Number(pick.value)+1,pages:p.count});blob=await canvasBlob(canvas);if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(blob);image.src=url}pick.onchange=paint;preview.append(pick,image,button('حفظ صورة الصفحة',()=>saveBlob(blob,'family-tree-'+(Number(pick.value)+1)+'.jpg'),'primary'),button('مشاركة الصورة',()=>shareFile(blob,'family-tree-'+(Number(pick.value)+1)+'.jpg'),'secondary'));preview.addEventListener('close',()=>{if(url)URL.revokeObjectURL(url)});await paint()}
 try{await load()}catch(e){body.textContent=e.message}return d;
}
export function initWholeTree(c){const rpc=(name,data)=>c.req('/rest/v1/rpc/'+name,{method:'POST',body:data}),open=()=>wholeTree({...c,rpc});const nav=c.button('شجرة العائلة',()=>c.busy(nav,open),'text-button');nav.id='whole-tree-open';nav.hidden=true;document.querySelector('.app-nav').append(nav);const admin=c.button('شجرة العائلة الكاملة والتصدير',open,'secondary');admin.id='whole-tree-admin';admin.hidden=true;document.getElementById('settings-section').append(admin);async function refresh(){if(!c.state.user||c.state.profile?.status!=='active'){nav.hidden=admin.hidden=true;return}try{const s=await rpc('whole_tree',{action:'settings'});nav.hidden=!s.enabled;admin.hidden=!s.admin}catch{nav.hidden=admin.hidden=true}}document.addEventListener('family:tree-visibility',refresh);return{refresh,reset(){nav.hidden=admin.hidden=true;document.querySelectorAll('.whole-tree-dialog,.tree-mobile-export').forEach(d=>d.remove())}}}
